def bubble_sort(nums:List[int])->List[int]:
    for i in range(len(nums)-1):
        swapped=False
        for j in range(len(nums)-1-i):
            if nums[j]>nums[j+1]:
                nums[j],nums[j+1]=nums[j+1],nums[j]
                swapped=True
        if not swapped:
            break
    return nums

def heapify(nums: List[int], heap_size: int, root: int) -> None:
    largest = root

    left = 2 * root + 1
    right = 2 * root + 2

    if left < heap_size and nums[left] > nums[largest]:
        largest = left

    if right < heap_size and nums[right] > nums[largest]:
        largest = right

    if largest != root:
        nums[root], nums[largest] = nums[largest], nums[root]

        heapify(nums, heap_size, largest)

def heap_sort(nums: List[int]) -> List[int]:
    n = len(nums)

    # 建立大顶堆
    for i in range(n // 2 - 1, -1, -1):
        heapify(nums, n, i)

    # 将最大值依次放到列表末尾
    for end in range(n - 1, 0, -1):
        nums[0], nums[end] = nums[end], nums[0]
        heapify(nums, end, 0)

    return nums

def insertion(nums:List[int])->List[int]:
    n=len(nums)
    for i in range(1,n):
        current=nums[i]
        j=i-1
        while j>=0 and nums[j]>current:
            nums[j+1]=nums[j]
            j=j-1
        nums[j+1]=current
    return nums

def merge(left:List[int],right:List[int])->List[int]:
    i=0
    j=0
    result=[]
    while i<len(left) and j<len(right):
        if left[i]<=right[j]:
            result.append(left[i])
            i+=1
        else:
            result.append(right[j])
            j+=1
    while i<len(left):
        result.append(left[i])
        i+=1
    while j<len(right):
        result.append(right[j])
        j+=1
    return result

def merge_sort(nums:List[int])->List[int]:
    if len(nums)<=1:
        return nums
    mid=len(nums)//2
    left=merge_sort(nums[:mid])
    right=merge_sort(nums[mid:])
    return merge(left,right)

def partition(nums:List[int],start:int,end:int)->int:
    tmp=nums[start]
    while start<end:
        while nums[end]>=tmp and start<end:
            end=end-1
        nums[start]=nums[end]
        while nums[start]<=tmp and start<end:
            start=start+1
        nums[end]=nums[start]
    nums[start]=tmp
    return start

def quick_sort(nums:List[int],start:int,end:int)->List[int]:
    if start<end:
        mid=partition(nums,start,end)
        quick_sort(nums,start,mid-1)
        quick_sort(nums,mid+1,end)
    return nums

def selection_sort(nums: List[int]) -> List[int]:
    n=len(nums)
    for i in range(n-1):
        min=i
        for j in range(i+1,n):
            if nums[j]<nums[min]:
                min=j
        nums[i],nums[min]=nums[min],nums[i]
    return nums

