def read_json_file(
    file_path: str,
) -> dict:
    """
    读取 JSON 配置文件，并要求根节点必须是对象。
    """
    path = Path(file_path)

    if not path.exists():
        raise FileNotFoundError(f"配置文件不存在：{file_path}")

    if not path.is_file():
        raise ValueError(f"输入路径不是文件：{file_path}")

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)

    if not isinstance(data, dict):
        raise ValueError("配置文件根节点必须是对象")

    return data

