def iter_file_lines(
    file_path: str,
) -> Iterator[str]:
    """
    使用生成器逐行读取文件，适合处理较大的文本文件。
    """
    path = Path(file_path)

    if not path.exists():
        raise FileNotFoundError(f"文件不存在：{file_path}")

    if not path.is_file():
        raise ValueError(f"路径不是文件：{file_path}")

    with path.open("r", encoding="utf-8") as file:
        for line in file:
            yield line.rstrip("\n")

def iter_chunk_batches(
    chunks: list[dict],
    batch_size: int,
) -> Iterator[list[dict]]:
    """
    按批次逐步返回 chunks，避免一次性创建所有批次。
    """
    if batch_size <= 0:
        raise ValueError("batch_size 必须大于 0")

    for start in range(
        0,
        len(chunks),
        batch_size,
    ):
        yield chunks[start:start + batch_size]

def calculate_total_length(
    chunks: list[dict],
) -> int:
    """
    使用生成器表达式计算所有 chunks 的总长度。
    """
    return sum(
        chunk.get("length", 0)
        for chunk in chunks
    )

def load_config_with_env(
    config_path: str,
    env_prefix: str = "PRACTICE",
) -> dict[str, Any]:
    """
    读取配置文件，并用指定前缀的环境变量覆盖同名配置项。
    """
    config = read_json_file(config_path)

    for key in list(config.keys()):
        env_key = f"{env_prefix}_{key}".upper()

        if env_key in os.environ:
            config[key] = os.environ[env_key]

    return config

def clean_text(self, text: str) -> str:
    """
    去掉首尾空白，并把连续空白字符压缩成一个空格。
    """
    return re.sub(r"\s+", " ", text.strip())

