        if query == "q1":
            return {
                "results": [
                    {"chunk_id": "a"},
                    {"chunk_id": "b"},
                ]
            }

        return {
            "results": [
                {"chunk_id": "x"},
                {"chunk_id": "z"},
            ]
        }

    result = evaluate_search_method(
        eval_cases=eval_cases,
