    payload = {
        "model": self.config.model_name,
        "input": texts,
    }

    data = self._post_json(
        url=url,
        payload=payload,
    )

    items = data.get("data")

    if not isinstance(items, list):
        raise ValueError("Embedding 返回中缺少 data")

    try:
        sorted_items = sorted(
            items,
