def normalize(
    self,
    vector: List[float],
) -> List[float]:
    """
    对向量做 L2 归一化，让余弦相似度计算更稳定。
    """
    norm = math.sqrt(
        sum(value * value for value in vector)
    )

    if norm == 0:
        return vector

    return [
        value / norm
        for value in vector
    ]

