@staticmethod
def _choose_mock_tool(
    query: str,
) -> str:
    lowered = query.lower()

    if any(
        keyword in lowered
        for keyword in [
            "目录",
            "结构",
            "模块",
            "文件树",
            "project structure",
        ]
    ):
        return "get_project_structure"

    if any(
        keyword in lowered
        for keyword in [
            "readme",
            "文档",
            "启动",
            "说明",
            "怎么用",
        ]
    ):
        return "search_documents"

    return "search_code"

