def validate_chunk_params(chunk_size: int, overlap: int) -> None:
    """
    校验 chunk 参数是否合法。
    """
    if chunk_size <= 0:
        raise ValueError("chunk_size 必须大于 0")

    if overlap < 0:
        raise ValueError("overlap 不能小于 0")

    if overlap >= chunk_size:
        raise ValueError("overlap 必须小于 chunk_size")

def chunk_text(
    text: str,
    chunk_size: int = DEFAULT_CHUNK_SIZE,
    overlap: int = DEFAULT_CHUNK_OVERLAP,
) -> List[str]:
    """
    对普通文档进行固定长度字符切分。
    """
    if not isinstance(text, str):
        raise TypeError("text 必须是字符串")

    validate_chunk_params(chunk_size, overlap)

    if not text or not text.strip():
        return []

    chunks = []
    start = 0

    while start < len(text):
        end = min(start + chunk_size, len(text))
        chunk = text[start:end].strip()

        if chunk:
            chunks.append(chunk)

        if end == len(text):
            break

        start = end - overlap

    return chunks

def split_code_content(
    content: str,
    max_chunk_chars: int,
    overlap: int,
) -> list[str]:
    """
    对超长函数、方法或模块内容做二次字符切分。
    """
    if max_chunk_chars <= 0:
        raise ValueError("max_chunk_chars 必须大于 0")

    if overlap < 0:
        raise ValueError("overlap 不能小于 0")

    if overlap >= max_chunk_chars:
        raise ValueError("overlap 必须小于 max_chunk_chars")

    if not content:
        return []

    parts: list[str] = []
    start = 0

    while start < len(content):
        end = min(start + max_chunk_chars, len(content))
        part = content[start:end]

        if part:
            parts.append(part)

        if end >= len(content):
            break

        start = end - overlap

    return parts

