def _safe_json_dumps(value: Any) -> str:
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            indent=2,
            default=str,
        )
    except TypeError:
        return str(value)

def _as_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value

    if hasattr(value, "model_dump"):
        dumped = value.model_dump()

        if isinstance(dumped, dict):
            return dumped

    return {"content": str(value)}

def extract_result_items(data: Any) -> list[dict[str, Any]]:
    '''这个函数负责从工具返回的 data 中提取结果列表。'''
    if data is None:
        return []

    if isinstance(data, list):
        return [
            _as_mapping(item)
            for item in data
        ]

    mapping = _as_mapping(data)

    for key in RESULT_LIST_KEYS:
        items = mapping.get(key)

        if isinstance(items, list):
            return [
                _as_mapping(item)
                for item in items
            ]

    return [mapping]

def _extract_content(item: dict[str, Any]) -> str:
    '''这个函数从 item 中提取证据正文。'''
    content_like_keys = {
        "content",
        "text",
        "snippet",
        "code",
        "document",
    }
    for key in (
        "content",
        "text",
        "snippet",
        "code",
        "document",
    ):
        value = item.get(key)

        if isinstance(value, str) and value.strip():
            return value.strip()

    if set(item.keys()) <= content_like_keys:
        return ""

    return _safe_json_dumps(item)

def _has_empty_explicit_content(
    item: dict[str, Any],
) -> bool:
    content_keys = (
        "content",
        "text",
        "snippet",
        "code",
        "document",
    )

    existing_values = [
        item.get(key)
        for key in content_keys
        if key in item
    ]

    if not existing_values:
        return False

    return not any(
        isinstance(value, str)
        and value.strip()
        for value in existing_values
    )

def _extract_score(item: dict[str, Any]) -> float | None:
    for key in (
        "rerank_score",
        "final_score",
        "score",
        "vector_score",
        "keyword_score",
        "match_score",
    ):
        value = item.get(key)

        if value is None:
            continue

        try:
            return float(value)
        except (TypeError, ValueError):
            continue

    return None

