def classify(
    self,
    query: str,
) -> QueryType:
    normalized_query = query.strip().lower()

    if not normalized_query:
        return "unknown"

    if self._contains_any(
        normalized_query,
        STRUCTURE_KEYWORDS,
    ):
        return "structure"

    if self._contains_any(
        normalized_query,
        DOCUMENT_KEYWORDS,
    ):
        return "document"

    if self._contains_any(
        normalized_query,
        CODE_KEYWORDS,
    ):
        return "code"

    return "unknown"

@staticmethod
def _contains_any(
    query: str,
    keywords: set[str],
) -> bool:
    return any(
        keyword.lower() in query
        for keyword in keywords
    )

    @staticmethod
    def extract_symbol_candidate(query: str) -> str | None:
        for pattern in (
            BACKTICK_SYMBOL_PATTERN,
            DOTTED_SYMBOL_PATTERN,
            SNAKE_CASE_PATTERN,
            CAMEL_CASE_PATTERN,
        ):
            '''
            优先级是：
1. 反引号里的符号
2. 带点符号
3. snake_case
4. CamelCase 类名
            '''
            match = pattern.search(query)

            if match:
                return match.group(1)

        return None

@staticmethod
def _is_code_semantic_query(query: str) -> bool:
    normalized_query = query.lower()
    keyword_groups = (
        CODE_SEMANTIC_KEYWORDS,
        CODE_SEMANTIC_ASCII_KEYWORDS,
    )

    return any(
        keyword.lower() in normalized_query
        for keywords in keyword_groups
        for keyword in keywords
    )

    def _build_rule_decision(
        self,
        query: str,
        *,
        decision_method: str,
    ) -> QueryDecision:
        '''
        这是规则决策函数。
它根据规则直接构造一个 QueryDecision。
        '''
        symbol_name = self.extract_symbol_candidate(query)
        query_type = self.rule_classifier.classify(query)

        if query_type == "unknown" and symbol_name:
            query_type = "code"

        if (
            query_type == "unknown"
            and self._is_code_semantic_query(query)
        ):
            query_type = "code"

        if query_type != "code":
            symbol_name = None

        if query_type == "structure":
            strategy = "structure"
        elif query_type == "code":
            strategy = "original" if symbol_name else "multi_query"
        elif query_type == "document":
            strategy = "multi_query"
        else:
            strategy = "none"

        return QueryDecision(
            query_type=query_type,
            retrieval_strategy=strategy,
            symbol_name=symbol_name,
            confidence=0.85 if query_type != "unknown" else 0.35,
            reason="根据关键词和代码标识符规则完成分类",
            decision_method=decision_method

