def validate(self) -> None:
    if self.candidate_top_k <= 0:
        raise ValueError("candidate_top_k 必须大于 0")

    if self.final_top_k <= 0:
        raise ValueError("final_top_k 必须大于 0")

    if self.final_top_k > self.candidate_top_k:
        raise ValueError("final_top_k 不能大于 candidate_top_k")

    if self.rewrite_count <= 0:
        raise ValueError("rewrite_count 必须大于 0")

    if self.max_context_chars <= 0:
        raise ValueError("max_context_chars 必须大于 0")

def _build_evidence_key(
    evidence: EvidenceItem,
) -> tuple:
    """
    构造证据去重键。

    优先使用 chunk_id；项目结构这类没有 chunk_id 的证据，
    使用 source_path、evidence_type 和 content 组合去重。
    """
    chunk_id = evidence.get("chunk_id")

    if chunk_id:
        return (
            "chunk_id",
            str(chunk_id),
        )

    qualified_name = evidence.get(
        "qualified_name"
    )

    if qualified_name:
        return (
            "symbol",
            str(
                evidence.get(
                    "source_path"
                )
                or ""
            ),
            str(qualified_name),
        )

    return (
        "content",
        str(evidence.get("source_path") or ""),
        str(evidence.get("evidence_type") or ""),
        str(evidence.get("content") or ""),
    )

def merge_unique_strings(
    current: list[str] | None,
    new: list[str] | None,
) -> list[str]:
    merged: list[str] = []

    for item in [
        *(current or []),
        *(new or []),
    ]:
        value = str(item).strip()

        if not value:
            continue

        if value in merged:
            continue

        merged.append(value)

    return merged

def route_by_query_type(
    state: CodeDocGraphState,
) -> str:
    """
    根据 query_type 决定进入哪个检索节点。
    """
    query_type = state.get(
        "query_type",
        "unknown",
    )

    if query_type == "code":
        return "code_search"

    if query_type == "document":
        return "document_search"

    if query_type == "structure":
        return "project_structure"

    return "fallback_answer"

def route_by_evidence_sufficiency(
    state: CodeDocGraphState,
) -> str:
    """
    根据证据是否充分决定生成答案或降级回答。
    """
    if state.get("evidence_sufficient") is True:
        return "build_answer"

    return "fallback_answer"

def route_after_analysis(
    state: CodeDocGraphState,
) -> AnalysisRoute:
    query_type = state.get(
        "query_type",
        "unknown",
    )

    symbol_name = state.get(
        "symbol_name"
    )

    if (
        query_type == "code"
        and symbol_name
    ):
        return "exact_symbol_lookup"

    if query_type == "code":
        return "code_retrieve"

    if query_type == "document":
        return "document_retrieve"

    if query_type == "structure":
        return "project_structure"

    return "fallback_answer"

