def _encode_data_lines(data: Any) -> list[str]:
    #这个函数负责生成 SSE 的 data: 行。
    if isinstance(data, str):
        text = data
    else:
        text = json.dumps(
            data,
            ensure_ascii=False,
            default=str,
        )

    lines = text.splitlines()#SSE 的 data 支持多行。

    if not lines:
        return ["data:"]

    return [f"data: {line}" for line in lines]

def encode_sse_event(event: SSEEvent) -> str:
    #这个函数把一个 SSEEvent 编码成完整 SSE 字符串。
    lines: list[str] = []

    if event.event_id is not None:
        lines.append(f"id: {event.event_id}")

    lines.append(f"event: {event.event}")

    if event.retry is not None:
        lines.append(f"retry: {event.retry}")

    lines.extend(_encode_data_lines(event.data))
    lines.append("")
    lines.append("")

    return "\n".join(lines)

def _extract_token_text(message_chunk: Any) -> str:
    #这个函数从模型流式 chunk 中提取文本。
    content = getattr(message_chunk, "content", "")

    if isinstance(content, str):
        return content

    if isinstance(content, list):
        parts: list[str] = []

        for item in content:
            if isinstance(item, dict):
                text = item.get("text")

                if text:
                    parts.append(str(text))

        return "".join(parts)

    return ""

def _compact_update(update_data: Any) -> dict[str, Any]:
    '''这个函数负责压缩 LangGraph 的 node update。'''
    if not isinstance(update_data, dict):
        return {"update": str(update_data)}

    compact: dict[str, Any] = {}

    for node_name, node_update in update_data.items():
        if node_name == "__interrupt__":
            compact[node_name] = str(node_update)
            continue

        if not isinstance(node_update, dict):
            compact[node_name] = str(node_update)
            continue

        compact[node_name] = {
            key: node_update[key]
            for key in (
                "execution_steps",
                "stop_reason",
                "approval_status",
                "completed",
                "answer",
                "error_message",
            )
            if key in node_update
        }

    return compact

