async def _stream_with_heartbeat(
    self,
    *,
    producer: Callable[[asyncio.Queue[Any]], Awaitable[None]],
    #一个异步函数 它接收 queue 它负责往 queue 里放事件
    request: Request,
) -> AsyncIterator[str]:#意思是这个函数会异步不断 yield 字符串
    queue: asyncio.Queue[Any] = asyncio.Queue()
    producer_task = asyncio.create_task(producer(queue))
    await asyncio.sleep(0)#让出一次事件循环，让 producer_task 有机会真正启动

    yield encode_sse_event(
        SSEEvent(
            event="connected",
            data={"status": "connected"},
            retry=3000,
        )
    )

    try:
        while True:
            if await request.is_disconnected():
                producer_task.cancel()
                break#如果前端断开了连接，就取消后台 producer，然后退出循环。

            try:
                item = await asyncio.wait_for(
                    queue.get(),
                    timeout=15,
                )#等 queue 里出现一个事件 但最多等 15 秒
            except TimeoutError:
                yield encode_sse_comment("heartbeat")#如果 15 秒没有事件，就发：: heartbeat
                                                     #这个不会触发业务事件，但能保持连接。

nt("heartbeat")#如果 15 秒没有事件，就发：: heartbeat
                                                         #这个不会触发业务事件，但能保持连接。
                    continue

                if item is STREAM_END:
                    break

                yield encode_sse_event(item)#编码然后 yield 给 FastAPI。 FastAPI 再推给前端。

        finally:
            if not producer_task.done():
                producer_task.cancel()

            try:
                await producer_task
            except asyncio.CancelledError:
                pass

class InvalidThreadIdError(ValueError)

Docstring:

    对外 thread_id 不合法时抛出的错误。

def validate_public_thread_id(
    thread_id: str,
) -> str:
    """
    校验用户传入的 thread_id，只允许安全、稳定、适合做命名空间的字符。
    """
    normalized = thread_id.strip()

    if not normalized:
        raise InvalidThreadIdError(
            "thread_id 不能为空"
        )

    if not THREAD_ID_PATTERN.fullmatch(
        normalized
    ):
        raise InvalidThreadIdError(
            "thread_id 只能包含字母、数字、点、下划线和短横线，"
            "长度为 1～120"
        )

    return normalized

def build_effective_thread_id(
    *,
    project_id: int,
    thread_id: str,
) -> str:
    """
    生成内部使用的 thread_id，把 project_id 放进命名空间，避免不同项目串记忆。
    """
    if project_id <= 0:
        raise ValueError(
            "project_id 必须大于 0"
        )

    normalized_thread_id = validate_public_thread_id(
        thread_id
    )

    return (
        f"project:{project_id}:"
        f"thread:{normalized_thread_id}"
    )

