def _build_unique_query_items(
    original_query: str,
    rewritten_queries: list[str],
) -> list[dict]:
    """
    构建去重后的 Multi-Query 检索项。
    """
    items = [
        {
            "query": original_query,
            "query_type": "original",
        }
    ]
    seen = {original_query}

    for rewritten_query in rewritten_queries:
        value = rewritten_query.strip()

        if not value:
            continue

        if value in seen:
            continue

        seen.add(value)
        items.append(
            {
                "query": value,
                "query_type": "rewrite",
            }
        )

    return items

