    从 JSON 文件中读取 chunks。
    """
    path=Path(input_path)

    if not path.exists():
        raise FileNotFoundError(f"chunks 文件不存在： {input_path}")

    content=path.read_text(encoding="utf-8")
    return json.loads(content)

