    """
    从候选检索结果中提取用于 Rerank 的完整文本。
    """
    content = candidate.get("content")

    if isinstance(content, str) and content.strip():
        return content

    preview = candidate.get("content_preview")

    if isinstance(preview, str) and preview.strip():
        return preview

    raise ValueError(
        f"候选结果缺少文本内容：{candidate.get('chunk_id')}"
    )

def validate_index_compatibility(
    metadata: Dict,
    query_provider: str,
    query_model: str,
    query_dimension: int,
) -> None:
    """
    校验查询使用的 Embedding 配置是否与索引元数据一致。
    """
    index_version = metadata.get("index_format_version")

    if index_version == "legacy":
        raise ValueError(
            "当前向量索引是旧格式，请重新调用 /index 构建新索引"
        )

    index_provider = metadata.get("embedding_provider")
    index_model = metadata.get("embedding_model")
    index_dimension = metadata.get("dimension")

    if index_provider != query_provider:
        raise ValueError(
            "Embedding Provider 不一致："
            f"索引使用 {index_provider}，查询使用 {query_provider}"
        )

    if index_model != query_model:
        raise ValueError(
            "Embedding 模型不一致："
            f"索引使用 {index_model}，查询使用 {query_model}"
        )

    if index_dimension != query_dimension:
        raise ValueError(
            "Embedding 向量维度不一致："
            f"索引维度 {index_dimension}，查询维度 {query_dimension}"
        )

def _extract_score(
    result: dict,
) -> float:
    score_names = [
        "rerank_score",
        "final_score",
        "multi_query_score",
        "score",
        "vector_score",
    ]

    for score_name in score_names:
        value = result.get(score_name)

        if value is None:
            continue

        try:
            return round(
                float(value),
                6,
            )
        except (
            TypeError,
            ValueError,
        ):
            continue

    return 0.0

