@staticmethod
def _parse_arguments(
    arguments: str | dict[str, Any],
) -> dict[str, Any]:
    if isinstance(arguments, dict):
        return arguments

    if not isinstance(arguments, str):
        raise ValueError(
            "工具参数必须是 JSON 字符串"
            "或字典"
        )

    value = arguments.strip()

    if not value:
        return {}

    try:
        parsed = json.loads(value)

    except json.JSONDecodeError as exc:
        raise ValueError(
            "工具参数不是合法 JSON："
            f"{exc.msg}"
        ) from exc

    if not isinstance(parsed, dict):
        raise ValueError(
            "工具参数 JSON 顶层必须是对象"
        )

    return parsed

@staticmethod
def _duration_ms(
    start_time: float,
) -> float:
    return round(
        (
            time.perf_counter()
            - start_time
        )
        * 1000,
        2,
    )

def _error_result(
    self,
    tool_name: str,
    error_code: str,
    error_message: str,
    start_time: float,
) -> ToolResult:
    return ToolResult(
        success=False,
        tool_name=tool_name,
        error_code=error_code,
        error_message=error_message,
        duration_ms=self._duration_ms(
            start_time
        ),
    )

