def to_openai_tool(self) -> dict:
    """
    转换成 OpenAI-compatible function tool。
    """
    parameters = (
        self.args_model.model_json_schema()
    )

    parameters.pop("title", None)

    return {
        "type": "function",
        "function": {
            "name": self.name,
            "description": self.description,
            "parameters": parameters,
        },
    }

def register(
    self,
    tool: ToolSpec,
) -> None:
    if not self.TOOL_NAME_PATTERN.fullmatch(
        tool.name
    ):
        raise ValueError(
            f"非法工具名称：{tool.name}"
        )

    if not tool.description.strip():
        raise ValueError(
            f"工具描述不能为空：{tool.name}"
        )

    if tool.name in self._tools:
        raise ValueError(
            f"工具已经注册：{tool.name}"
        )

    self._tools[tool.name] = tool

def get(
    self,
    tool_name: str,
) -> ToolSpec | None:
    return self._tools.get(tool_name)

def require(
    self,
    tool_name: str,
) -> ToolSpec:
    tool = self.get(tool_name)

    if tool is None:
        raise KeyError(
            f"工具不存在：{tool_name}"
        )

    return tool

def list_specs(self) -> list[ToolSpec]:
    return [
        self._tools[name]
        for name in self.names()
    ]

def to_openai_tools(
    self,
) -> list[dict]:
    return [
        tool.to_openai_tool()
        for tool in self.list_specs()
    ]

def __contains__(
    self,
    tool_name: str,
) -> bool:
    return tool_name in self._tools

def iter_batches(
    items: Sequence[T],
    batch_size: int,
) -> Iterator[list[T]]:
    """
    使用生成器逐批返回数据，避免一次性创建所有批次列表。
    """
    if batch_size <= 0:
        raise ValueError("batch_size 必须大于 0")

    for start in range(
        0,
        len(items),
        batch_size,
    ):
        yield list(
            items[start:start + batch_size]
        )

def split_batches(
    items: Sequence[T],
    batch_size: int,
) -> List[List[T]]:
    """
    将列表按 batch_size 拆分成多个批次，保留旧接口兼容 Day24 代码。
    """
    return list(
        iter_batches(
            items=items,
            batch_size=batch_size,
        )
    )

def normalize_content(content: str) -> str:
    """
    统一换行符，避免 Windows 和 Linux 换行差异
    导致同一份内容产生不同哈希。
    """
    if not isinstance(content, str):
        raise TypeError("content 必须是字符串")

    return (
        content
        .replace("\r\n", "\n")
        .replace("\r", "\n")
    )

def compute_content_hash(content: str) -> str:
    """
    计算文本内容的 SHA-256 哈希。
    """
    normalized_content = normalize_content(content)

    return hashlib.sha256(
        normalized_content.encode("utf-8")
    ).hexdigest()

